import {
  Navigate,
  Route,
  Routes,
  useLocation,
  useNavigate,
} from "react-router-dom";
import { useLenis } from "lenis/react";
import { Archive, ChevronRight, X } from "lucide-react";
import {
  lazy,
  startTransition,
  Suspense,
  useCallback,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { SiteIntro } from "./components/intro/SiteIntro";
import { LiquidGlass } from "./components/reactbits/LiquidGlass";
import { NotFoundPage } from "./components/not-found/NotFoundPage";
import { PersistentDock } from "./components/navigation/PersistentDock";
import { useAccountStore } from "./lib/auth";
import { cn } from "./lib/cn";
import { prefetchHomeLobby } from "./lib/routePrefetch";
import { useLeafia } from "./store/leafia";
import { ThemeController } from "./theme/ThemeController";

/*
 * 首屏只装骨架：开场幕布、码头、主题。重的东西全部懒加载——
 * - HomeLobby 背着 three.js（全站最重的一块）；
 * - BookRoute 背后是 knowledgeCatalog（几十万字教材正文）与两个阅读器；
 * - LandingPage 是 /welcome 的整页，由开场幕布播放期间预取回来。
 * 主包因此不必在幕布播放前解析它们，开场动画能更早开始也更少被打扰。
 */
const HomeLobby = lazy(() =>
  import("./components/home/HomeLobby").then((module) => ({
    default: module.HomeLobby,
  })),
);
const LandingPage = lazy(() =>
  import("./components/landing/LandingPage").then((module) => ({
    default: module.LandingPage,
  })),
);
const BookRoute = lazy(() => import("./components/book/BookRoute"));
const KnowledgeLibraryPage = lazy(() =>
  import("./components/knowledge/KnowledgeLibraryPage").then((module) => ({
    default: module.KnowledgeLibraryPage,
  })),
);
const PracticeLibraryPage = lazy(() =>
  import("./components/practice/PracticeLibraryPage").then((module) => ({
    default: module.PracticeLibraryPage,
  })),
);
const PracticeDrillPage = lazy(() =>
  import("./components/practice/PracticeDrillPage").then((module) => ({
    default: module.PracticeDrillPage,
  })),
);
const CorpusPage = lazy(() =>
  import("./components/corpus/CorpusPage").then((module) => ({
    default: module.CorpusPage,
  })),
);
const VocabularyPage = lazy(() =>
  import("./components/vocabulary/VocabularyPage").then((module) => ({
    default: module.VocabularyPage,
  })),
);
const ComponentLabPage = lazy(() =>
  import("./components/reactbits/ComponentLabPage").then((module) => ({
    default: module.ComponentLabPage,
  })),
);
const AccountPage = lazy(() =>
  import("./components/auth/AccountPage").then((module) => ({
    default: module.AccountPage,
  })),
);

function ArchiveDrawer() {
  const navigate = useNavigate();
  const { archiveOpen, setArchiveOpen } = useLeafia();
  if (!archiveOpen) return null;

  return (
    <div
      className="drawer-backdrop"
      role="presentation"
      onClick={() => setArchiveOpen(false)}
    >
      <LiquidGlass
        as="aside"
        className="archive-drawer"
        role="dialog"
        aria-modal="true"
        aria-label="Archive"
        intensity="strong"
        onClick={(event) => event.stopPropagation()}
      >
        <header>
          <div>
            <span className="eyebrow">Stored beneath the desk</span>
            <h2>Archive</h2>
          </div>
          <button
            type="button"
            className="icon-button"
            onClick={() => setArchiveOpen(false)}
            aria-label="Close archive"
          >
            <X size={18} />
          </button>
        </header>
        <div className="archive-list">
          {[
            ["Last summer’s reading list", "18 notes · archived 2 weeks ago"],
            ["Interview vocabulary, first draft", "42 phrases · archived last month"],
            ["Teaching observation notes", "9 pages · archived in June"],
          ].map(([title, meta]) => (
            <button
              type="button"
              key={title}
              onClick={() => {
                setArchiveOpen(false);
                navigate("/library");
              }}
            >
              <Archive size={18} />
              <span>
                <strong>{title}</strong>
                <small>{meta}</small>
              </span>
              <ChevronRight size={16} />
            </button>
          ))}
        </div>
      </LiquidGlass>
    </div>
  );
}

function Toast() {
  const { toast } = useLeafia();
  return (
    <div className={cn("toast", toast && "is-visible")} role="status">
      {toast?.message}
    </div>
  );
}

/** 懒加载页面下载的那几百毫秒以前是一片空白，现在用整页幕布盖住（styles.css 的 .route-curtain）。 */
function LazyRoute({ children }: { children: ReactNode }) {
  return (
    <Suspense fallback={<div className="route-curtain" aria-hidden="true" />}>
      {children}
    </Suspense>
  );
}

export function App() {
  const location = useLocation();
  const navigate = useNavigate();
  const lenis = useLenis();
  const bootstrap = useLeafia((state) => state.bootstrap);
  const bootstrapAccount = useAccountStore((state) => state.bootstrap);
  const initialPathRef = useRef(location.pathname);
  const introPlanned =
    initialPathRef.current === "/" || initialPathRef.current === "/welcome";
  const [introOpen, setIntroOpen] = useState(introPlanned);
  // 幕布由 introOpen 控制，路由由 routeLive 控制：两者刻意分开——退场开始
  // 前路由就挂载（首帧渲染藏进幕布里），幕布自己播完再卸载。
  const [routeLive, setRouteLive] = useState(!introPlanned);

  useEffect(() => {
    void bootstrap();
    void bootstrapAccount();
  }, [bootstrap, bootstrapAccount]);

  // 幕布播放期间把 /welcome 的包取回来，揭幕时落地页已经就位。
  useEffect(() => {
    if (!introOpen) return undefined;
    const timer = window.setTimeout(() => {
      void import("./components/landing/LandingPage").catch(() => undefined);
    }, 600);
    return () => window.clearTimeout(timer);
  }, [introOpen]);

  // 在 welcome 上停留一会儿后，后台把书架（three.js）预热，「进入知识库」
  // 或目录里的书架入口就不会撞上整包下载。指针悬停目标按钮时会更早触发。
  useEffect(() => {
    if (introOpen || location.pathname !== "/welcome") return undefined;
    const timer = window.setTimeout(() => prefetchHomeLobby(), 2_600);
    return () => window.clearTimeout(timer);
  }, [introOpen, location.pathname]);

  // 幕布期间路由已经挂在幕后（见 routeLive），也就是说背后的落地页此刻是
  // 可滚的：不拦的话，停留+退场这两秒里滚轮或空格键会把还没揭幕的页面滚
  // 走，揭幕时用户落在半页中间。幕布盖着的这段时间把滚动整个停住——Lenis
  // 的平滑滚动要停，原生路径（键盘、滚动条）用 body overflow 锁（和
  // AuthDialog 同一套做法），揭幕后再原样交还。
  useEffect(() => {
    if (!introOpen) return undefined;
    lenis?.stop();
    const { body } = document;
    const previousOverflow = body.style.overflow;
    body.style.overflow = "hidden";
    return () => {
      lenis?.start();
      body.style.overflow = previousOverflow;
    };
  }, [introOpen, lenis]);

  /** 幕布开始收场：把路由切到 /welcome 挂到幕布后面。
   *
   *  两个更新必须一起进 startTransition：react-router 的 navigate 走的是
   *  低优先级更新，如果 routeLive 在普通优先级先提交，React 会先渲染一帧
   *  「routeLive 已开、location 还是 /」——首页路由当场把 HomeLobby
   *  （three.js 整块）拉起来下载。同车道合并后只有一次渲染，看到的就是
   *  /welcome，HomeLobby 留给点「进入知识库」时再取。 */
  const handleIntroExiting = useCallback(() => {
    startTransition(() => {
      navigate("/welcome", { replace: true });
      setRouteLive(true);
    });
  }, [navigate]);

  /** 幕布退场动画播完，卸载幕布本身。 */
  const handleIntroFinished = useCallback(() => {
    setIntroOpen(false);
  }, []);

  return (
    <div className="leafia-app">
      <SiteIntro
        open={introOpen}
        onExiting={handleIntroExiting}
        onFinished={handleIntroFinished}
      />
      <ThemeController />
      <div className="motion-route-stage" data-motion-root>
        {routeLive ? (
          <Routes>
          {/* 打开 Leafia 就是走进书房：首页空间即书架本体。原来的动效落地页
              挪到 /welcome —— 它还在，只是不再是正门。 */}
          <Route
            path="/"
            element={
              <LazyRoute>
                <HomeLobby />
              </LazyRoute>
            }
          />
          <Route
            path="/welcome"
            element={
              <LazyRoute>
                <LandingPage />
              </LazyRoute>
            }
          />
          <Route
            path="/shelf"
            element={
              <LazyRoute>
                <HomeLobby />
              </LazyRoute>
            }
          />
          <Route path="/study" element={<Navigate to="/shelf" replace />} />
          <Route
            path="/inkverse/:bookId"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/library"
            element={<KnowledgeLibraryPage />}
          />
          <Route
            path="/library/:categoryId"
            element={<KnowledgeLibraryPage />}
          />
          <Route
            path="/write/:noteId"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/write/:noteId/:pageId"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/book/:bookId"
            element={
              <LazyRoute>
                <BookRoute />
              </LazyRoute>
            }
          />
          <Route
            path="/corpus"
            element={
              <LazyRoute>
                <CorpusPage />
              </LazyRoute>
            }
          />
          <Route path="/reading" element={<Navigate to="/library" replace />} />
          <Route
            path="/reading/:chapterId"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/practice"
            element={
              <LazyRoute>
                <PracticeLibraryPage />
              </LazyRoute>
            }
          />
          <Route
            path="/drill/:trackId"
            element={
              <LazyRoute>
                <PracticeDrillPage />
              </LazyRoute>
            }
          />
          <Route
            path="/vocabulary"
            element={
              <LazyRoute>
                <VocabularyPage />
              </LazyRoute>
            }
          />
          <Route
            path="/components"
            element={
              <LazyRoute>
                <ComponentLabPage />
              </LazyRoute>
            }
          />
          {/* 用户界面：目录面板里那块账号区按「查看用户界面」就到这儿，
              没登录也进得来（这一页会说明数据现在存在哪儿）。 */}
          <Route
            path="/account"
            element={
              <LazyRoute>
                <AccountPage />
              </LazyRoute>
            }
          />
          <Route path="*" element={<NotFoundPage />} />
          </Routes>
        ) : (
          <div className="leafia-opening-stage" aria-hidden="true" />
        )}
      </div>
      <PersistentDock />
      <ArchiveDrawer />
      <Toast />
    </div>
  );
}
