import { create } from "zustand";
import {
  LEGACY_SKIN_STORAGE_KEY,
  THEME_PENDING_STORAGE_KEY,
  THEME_PRESETS,
  THEME_STORAGE_KEY,
  isThemeId,
  resolveStoredThemeId,
  themeCssVariables,
  type ThemeId,
} from "../theme/palettes";

function storageAvailable() {
  return typeof localStorage !== "undefined";
}

export function loadThemeId(): ThemeId {
  if (!storageAvailable()) return "moon";
  try {
    const current = localStorage.getItem(THEME_STORAGE_KEY);
    if (isThemeId(current)) return current;
    const legacy = localStorage.getItem(LEGACY_SKIN_STORAGE_KEY);
    if (legacy) {
      const migrated = resolveStoredThemeId(legacy);
      localStorage.setItem(THEME_STORAGE_KEY, migrated);
      localStorage.removeItem(LEGACY_SKIN_STORAGE_KEY);
      return migrated;
    }
  } catch {
    // Storage can be unavailable in private browsing. The default still works.
  }
  return "moon";
}

export function hasPendingThemeSync() {
  if (!storageAvailable()) return false;
  try {
    return localStorage.getItem(THEME_PENDING_STORAGE_KEY) === "1";
  } catch {
    return false;
  }
}

function persistThemeId(themeId: ThemeId) {
  if (!storageAvailable()) return;
  try {
    localStorage.setItem(THEME_STORAGE_KEY, themeId);
  } catch {
    // The in-memory selection remains valid for this session.
  }
}

function persistPending(pending: boolean) {
  if (!storageAvailable()) return;
  try {
    if (pending) localStorage.setItem(THEME_PENDING_STORAGE_KEY, "1");
    else localStorage.removeItem(THEME_PENDING_STORAGE_KEY);
  } catch {
    // The in-memory flag remains valid for this session.
  }
}

export function applyThemeToDocument(themeId: ThemeId) {
  if (typeof document === "undefined") return;
  const preset = THEME_PRESETS[themeId];
  const root = document.documentElement;
  root.dataset.theme = themeId;
  root.dataset.appearance = preset.appearance;
  root.style.colorScheme = preset.appearance;

  for (const [property, value] of Object.entries(themeCssVariables(preset))) {
    root.style.setProperty(property, value);
  }

  const meta = document.querySelector<HTMLMetaElement>(
    'meta[name="theme-color"]',
  );
  if (meta) meta.content = preset.tokens.pageMid;
}

interface ThemeState {
  themeId: ThemeId;
  pendingSync: boolean;
  setTheme: (themeId: ThemeId) => void;
  applyRemoteTheme: (themeId: ThemeId) => void;
  markSynced: () => void;
  syncFromStorage: () => void;
}

export const useThemeStore = create<ThemeState>((set) => ({
  themeId: loadThemeId(),
  pendingSync: hasPendingThemeSync(),
  setTheme(themeId) {
    if (!isThemeId(themeId)) return;
    persistThemeId(themeId);
    persistPending(true);
    applyThemeToDocument(themeId);
    set({ themeId, pendingSync: true });
  },
  applyRemoteTheme(themeId) {
    if (!isThemeId(themeId)) return;
    persistThemeId(themeId);
    persistPending(false);
    applyThemeToDocument(themeId);
    set({ themeId, pendingSync: false });
  },
  markSynced() {
    persistPending(false);
    set({ pendingSync: false });
  },
  syncFromStorage() {
    const themeId = loadThemeId();
    const pendingSync = hasPendingThemeSync();
    applyThemeToDocument(themeId);
    set({ themeId, pendingSync });
  },
}));

export function initializeTheme() {
  applyThemeToDocument(useThemeStore.getState().themeId);
}
