import { IdCard, LogIn, LogOut, UserRound } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { useLeafiaAccount } from "../../lib/auth";
import "./account-menu-block.css";

/**
 * 目录最上面那块账号区（占面板的 panelTop 槽位，在 LIBRARY/PIANO 分组之前）。
 *
 * 登录不再藏在设置里：拉开目录（左上角那颗 Leafia 铭牌）就能看见自己是谁，
 * 或者直接登录 / 注册。登录以后便条、主题、单词本这些个人数据跟着账号走，
 * 走的是我们自己的 API（见 lib/accountApi）。
 *
 * 颜色跟着皮肤走：样式全用 --theme-* 令牌（见 account-menu-block.css），
 * 默认皮肤月灰紫打开就是灰紫的一套。
 *
 * 点「登录 / 注册」时先把目录折起来 —— 登录浮层铺在整页之上，
 * 菜单留在后面开着会挡住它一半。
 */
export function AccountMenuBlock({
  onOpenAuth,
  onCloseMenu,
}: {
  onOpenAuth: (view?: "signin" | "register") => void;
  onCloseMenu: () => void;
}) {
  const account = useLeafiaAccount();
  const navigate = useNavigate();
  const signedIn = account.status === "signed-in" ? account.user : null;

  if (signedIn) {
    return (
      <section className="sm-account" aria-label="账号">
        <span className="sm-account__kicker">Account · 账号</span>
        <p className="sm-account__who">
          <span className="sm-account__avatar" aria-hidden="true">
            <UserRound size={16} />
          </span>
          <span>
            <strong>{signedIn.displayName}</strong>
            <small>
              {signedIn.emailMasked ?? signedIn.phoneMasked ?? "Leafia Account"}
            </small>
          </span>
        </p>
        <p className="sm-account__note">便条与主题跟着这个账号走，换台设备也还在。</p>
        <div className="sm-account__actions">
          {/* 想把自己这一摊看全（这个名字、这些数据挂在哪儿）就进用户界面；
              只想退出的话，旁边那颗是退出。 */}
          <button
            type="button"
            className="sm-account__action is-primary"
            onClick={() => {
              onCloseMenu();
              navigate("/account");
            }}
          >
            <IdCard size={14} />
            查看用户界面
          </button>
          <button
            type="button"
            className="sm-account__action is-quiet"
            disabled={account.busy}
            onClick={() => void account.signOut()}
          >
            <LogOut size={14} />
            退出登录
          </button>
        </div>
      </section>
    );
  }

  return (
    <section className="sm-account" aria-label="账号">
      <span className="sm-account__kicker">Account · 账号</span>
      <p className="sm-account__note">
        不登录也能用，便条存在这台设备上；登录后个人数据跟着账号走。
      </p>
      <div className="sm-account__actions">
        <button
          type="button"
          className="sm-account__action is-primary"
          onClick={() => {
            onCloseMenu();
            onOpenAuth("signin");
          }}
        >
          <LogIn size={14} />
          登录 / 注册
        </button>
      </div>
      {account.error ? (
        <p className="sm-account__error" role="status">
          {account.error}
        </p>
      ) : null}
    </section>
  );
}

export default AccountMenuBlock;
